\begin{tikzpicture}[every node/.style={font=\large}]
\draw (-1.6,0) -- (-1.6,1.2);
\draw (1.6,0) -- (1.6,1.2);
\draw (-1.6,0) arc (180:360:1.6 and 0.45);
\draw[dashed] (1.6,0) arc (0:180:1.6 and 0.45);
\draw (-1.6,1.2) arc (180:360:1.6 and 0.45);
\draw[dashed] (1.6,1.2) arc (0:180:1.6 and 0.45);
\draw (-1.6,1.2) -- (0,2.4);
\draw (1.6,1.2) -- (0,2.4) node[midway,above right,fill=white,inner sep=1pt] {$5\text{ cm}$};
\fill (0,0) circle (1.2pt);
\draw[-{Stealth}] (0,0)--(1.6,0) node[midway,below,fill=white,inner sep=1pt] {$4\text{ cm}$};
\draw[{Stealth}-{Stealth}] (-1.95,0)--(-1.95,1.2) node[midway,left] {$3\text{ cm}$};
\end{tikzpicture}
